from taf.internal.managedobject import Using
from taf.collectors.base import StartableCollector, Decorating
from taf.internal.execution.base import ExecutionError
from threading import Thread
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TcpdumpCollector(Using("tool_executor"), Using("file_getter"), StartableCollector):
    """
    Collector for pcap files with message traces using "tcpdump".
    """

    def __init__(
            self,
            capturing_strategy,
            options=None,
            tcpdump_path="tcpdump",
            start_timeout=10,
            stop_timeout=3,
            target_file_name=None,
            **kwargs):
        super(TcpdumpCollector, self).__init__(**kwargs)
        self._capturing_strategy = capturing_strategy
        self._options = " {options}".format(options=options) if options else ""
        self._tcpdump_path = tcpdump_path
        self._start_timeout = float(start_timeout)
        self._stop_timeout = float(stop_timeout)
        self._target_file_name = target_file_name if target_file_name \
            else "{name}.pcap".format(name=self._name)
        self._log_path = "/tmp/tcpdump_{name}.pcap".format(name=self._name)
        self._remote_path = self._capturing_strategy.get_remote_path(log_path=self._log_path)
        self._sudo_prefix = None
        self._process = None

    def _get_sudo_prefix(self):
        return self._tool_executor.sudo_prefix()

    def _setup(self):
        self._sudo_prefix = self._get_sudo_prefix()
        self._process_and_file_cleanup()

    def _process_and_file_cleanup(self):
        self._tool_executor.raw_execute(
            """{sudo_prefix}bash -c '"""
            """kill $(<"/tmp/{name}.pid"); """
            """rm "/tmp/{name}.pid"'""".format(
                name=self.name,
                sudo_prefix=self._sudo_prefix).encode('utf-8'))
        self._file_cleanup()

    def _start(self):
        self._do_start()
        self._capturing_strategy.start(
            log_path=self._log_path,
            process=self._process)
        self._wait_for_start_completed()

    def _do_start(self):
        start_command = self._start_command()
        self._process = self._tool_executor.start(start_command, use_tty=False)

    def _start_command(self):
        return (
            '''{sudo_prefix}bash -c "echo ""$""$ > '/tmp/{name}.pid'; '''
            '''exec '''
            '''\'{tcpdump_path}\' -U -w -{options}{remote_path}"''').format(
            name=self.name,
            sudo_prefix=self._sudo_prefix,
            remote_path=self._remote_path,
            tcpdump_path=self._tcpdump_path,
            options=self._options).encode('utf-8')

    def _wait_for_start_completed(self):
        stderr_output = self._process.stderr.read_until_string(
            string=b"listening on",
            timeout=self._start_timeout)
        if b'listening on' not in stderr_output:
            raise ExecutionError(
                stdout=None,
                stderr=stderr_output,
                exit_status=self._process.exit_status)
        else:
            stderr_output += self._process.stderr.read_line(
                timeout=self._start_timeout)
            logger.info(f"Tcpdump started with stderr output: {stderr_output!r}")

    def _stop(self):
        stdout, stderr, exit_status = self._tool_executor.raw_execute(
            """{sudo_prefix}bash -c '"""
            """kill $(<"/tmp/{name}.pid"); """
            """rm "/tmp/{name}.pid"'""".format(
                name=self.name,
                sudo_prefix=self._sudo_prefix).encode('utf-8'))
        if exit_status or stderr:
            logger.warning("Terminating process failed with error '{stderr}' with exit_status {exit_status}.".format(
                stderr=stderr,
                exit_status=exit_status))
        self._wait_till_process_terminated()

    def _wait_till_process_terminated(self):
        self._capturing_strategy.wait(timeout=self._stop_timeout)
        self._process.wait(timeout=self._stop_timeout)

    def _collect(self, target_dir):
        self._file_getter.get_file(
            source_path=self._log_path,
            target_path="{target_dir}/{target_file_name}".format(
                target_dir=target_dir,
                target_file_name=self._target_file_name))

    def _teardown(self):
        self._process_and_file_cleanup()

    def _file_cleanup(self):
        self._capturing_strategy.file_cleanup(
            sudo_prefix=self._sudo_prefix,
            log_path=self._log_path)


class RemoteCaptureStrategy(Using("tool_executor")):
    def get_remote_path(self, log_path):
        return " >'{}'".format(log_path)

    def start(self, log_path, process):
        pass

    def wait(self, timeout):
        pass

    def file_cleanup(self, sudo_prefix, log_path):
        self._tool_executor.execute(
            "{sudo_prefix}rm -f '{log_path}'".format(
                sudo_prefix=sudo_prefix,
                log_path=log_path).encode('utf-8'))


class LocalCaptureStrategy(Using("local_executor")):

    def __init__(self, **kwargs):
        super(LocalCaptureStrategy, self).__init__(**kwargs)
        self._thread = None

    def get_remote_path(self, log_path):
        return ""

    def start(self, log_path, process):

        def run(log_path, process):
            with self._open_log_path(log_path) as logfile:
                while True:
                    data = process.stdout.read(size=1024)
                    if not data:
                        break
                    logfile.write(data)

        self._thread = Thread(target=run, args=(log_path, process))
        self._thread.daemon = True
        self._thread.start()

    def _open_log_path(self, log_path):
        return open(log_path, "wb")

    def wait(self, timeout):
        self._thread.join(timeout=timeout)

    def file_cleanup(self, sudo_prefix, log_path):
        self._local_executor.execute(
            "rm -f '{log_path}'".format(
                log_path=log_path).encode('utf-8'))


class PdumpMirrorCollector(Decorating,
                           Using("port"),
                           Using("tool_executor"),
                           StartableCollector):

    def _setup(self):
        self._mirroring_process = self._tool_executor.start('hal-cli pdump mirror {port} lo'.format(
            port=self._port).encode('utf-8'),
            use_tty=True)

    def _teardown(self):
        if self._mirroring_process.is_running:
            self._mirroring_process.stdin.write("\x03".encode())
            self._mirroring_process.wait(timeout=10)
